import os
from typing import Any, Dict, List, Optional

import requests


def extract_invoice_fields(invoice_url: str, api_key: Optional[str] = None) -> Dict[str, Any]:
    """
    Extract vendor, date, total, and line items from an invoice image/PDF URL
    using Azure AI Document Intelligence (prebuilt-invoice model).

    Requires:
      - AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT
      - AZURE_DOCUMENT_INTELLIGENCE_KEY
    """
    endpoint = os.getenv("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    key = api_key or os.getenv("AZURE_DOCUMENT_INTELLIGENCE_KEY")

    if not endpoint or not key:
        raise ValueError(
            "Missing Azure Document Intelligence configuration. "
            "Set AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT and AZURE_DOCUMENT_INTELLIGENCE_KEY."
        )

    analyze_url = endpoint.rstrip("/") + "/documentintelligence/documentModels/prebuilt-invoice:analyze?api-version=2024-02-29-preview"
    headers = {
        "Ocp-Apim-Subscription-Key": key,
        "Content-Type": "application/json",
    }
    payload = {"urlSource": invoice_url}

    resp = requests.post(analyze_url, headers=headers, json=payload, timeout=60)
    resp.raise_for_status()

    operation_url = resp.headers.get("operation-location")
    if not operation_url:
        raise RuntimeError("Azure Document Intelligence response missing operation-location header.")

    result = None
    for _ in range(60):
        poll = requests.get(
            operation_url,
            headers={"Ocp-Apim-Subscription-Key": key},
            timeout=30,
        )
        poll.raise_for_status()
        result = poll.json()
        status = result.get("status")
        if status in {"succeeded", "failed"}:
            break

    if not result or result.get("status") != "succeeded":
        raise RuntimeError(f"Invoice analysis did not succeed: {result.get('status') if result else 'unknown'}")

    analyze_result = result.get("analyzeResult", {})
    documents = analyze_result.get("documents", [])
    doc = documents[0] if documents else {}

    fields = doc.get("fields", {})

    def field_value(name: str) -> Any:
        field = fields.get(name, {})
        if isinstance(field, dict):
            return field.get("valueString") or field.get("content") or field.get("valueDate") or field.get("valueNumber")
        return None

    vendor = field_value("VendorName")
    date = field_value("InvoiceDate")
    total = field_value("InvoiceTotal")

    line_items: List[Dict[str, Any]] = []
    for item in fields.get("Items", {}).get("valueArray", []) if isinstance(fields.get("Items"), dict) else []:
        item_fields = item.get("valueObject", {}) if isinstance(item, dict) else {}
        line_items.append(
            {
                "description": item_fields.get("Description", {}).get("valueString")
                or item_fields.get("Description", {}).get("content"),
                "quantity": item_fields.get("Quantity", {}).get("valueNumber")
                or item_fields.get("Quantity", {}).get("content"),
                "unit_price": item_fields.get("UnitPrice", {}).get("valueCurrency", {}).get("amount")
                if isinstance(item_fields.get("UnitPrice", {}).get("valueCurrency"), dict)
                else item_fields.get("UnitPrice", {}).get("content"),
                "amount": item_fields.get("Amount", {}).get("valueCurrency", {}).get("amount")
                if isinstance(item_fields.get("Amount", {}).get("valueCurrency"), dict)
                else item_fields.get("Amount", {}).get("content"),
            }
        )

    return {
        "vendor": vendor,
        "date": date,
        "total": total,
        "line_items": line_items,
        "raw": result,
    }
